(1, 'CAR', 'Porsche', '911 Carrera 4S', 'CAR', 'PETROL', 'AUTOMATIC', 320.00, 500.00, 'https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=1200&q=80', 'Legendary German performance engineered with twin-turbo flat-six power, all-wheel drive stability, and unmistakable styling.', 1, 4.9, 'Downtown Executive Hub', 'Sport Chrono Package, Burmester 3D Sound, Adaptive Sports Seats, Carbon Fiber Trim, Apple CarPlay', 4, 2, 'Sports Coupe', 1, NULL, NULL, NULL),
(2, 'CAR', 'Mercedes-Benz', 'AMG GT Coupe', 'CAR', 'PETROL', 'AUTOMATIC', 295.00, 450.00, 'https://images.unsplash.com/photo-1617814076367-b759c7d7e738?auto=format&fit=crop&w=1200&q=80', 'Handcrafted 4.0L V8 Biturbo powerhouse delivering race-bred aerodynamics and bespoke interior luxury.', 1, 4.9, 'Airport Terminal A', 'AMG Performance Exhaust, Nappa Leather Interior, 360 Camera, Panamericana Grille, Head-Up Display', 2, 2, 'Coupe', 1, NULL, NULL, NULL),
(3, 'CAR', 'BMW', 'M5 Competition', 'CAR', 'PETROL', 'AUTOMATIC', 245.00, 400.00, 'https://images.unsplash.com/photo-1555215695-3004980ad54e?auto=format&fit=crop&w=1200&q=80', 'Super-sedan perfection combining 617 horsepower with executive cabin comfort and precise M xDrive dynamics.', 1, 4.8, 'Downtown Executive Hub', 'M Carbon Ceramic Brakes, Bowers & Wilkins Diamond Sound, Bowers HUD, Executive Seating, Wireless Charging', 5, 3, 'Sedan', 1, NULL, NULL, NULL),
(4, 'CAR', 'Audi', 'RS6 Avant', 'CAR', 'PETROL', 'AUTOMATIC', 230.00, 350.00, 'https://images.unsplash.com/photo-1603584173870-7f23fdae1b7a?auto=format&fit=crop&w=1200&q=80', 'The ultimate performance estate. Widebody stance, twin-turbo V8 thrust, and cavernous cargo capacity for long-distance cruising.', 1, 4.8, 'Suburban Plaza', 'Bang & Olufsen Advanced 3D, Quattro All-Wheel Steering, Matrix LED, Panoramic Roof, Heated Steering', 5, 4, 'Avant / Estate', 1, NULL, NULL, NULL),
(5, 'CAR', 'Tesla', 'Model S Plaid', 'CAR', 'ELECTRIC', 'AUTOMATIC', 190.00, 300.00, 'https://images.unsplash.com/photo-1560958089-b8a1929cea89?auto=format&fit=crop&w=1200&q=80', 'Unrivaled 1,020 hp electric acceleration reaching 0-60 mph in 1.99s, paired with high-tech autopilot and yoke steering.', 1, 4.9, 'Airport Terminal A', 'Full Self-Driving Capability, 17-inch Cinematic Screen, 396 Mile Range, Glass Roof, Ultra High Fidelity Audio', 5, 3, 'Sedan', 1, NULL, NULL, NULL),
(6, 'CAR', 'Range Rover', 'SV Autobiography', 'CAR', 'DIESEL', 'AUTOMATIC', 265.00, 450.00, 'https://images.unsplash.com/photo-1563720223185-11003d516935?auto=format&fit=crop&w=1200&q=80', 'Peerless British luxury and off-road supremacy with executive rear seating and whisper-quiet acoustic cabin insulation.', 1, 4.8, 'Downtown Executive Hub', 'Executive Class Rear Seating, Meridian Signature Sound, Air Suspension, Hot Stone Massage, Soft-Close Doors', 5, 4, 'Luxury SUV', 1, NULL, NULL, NULL),
(7, 'BIKE', 'Ducati', 'Panigale V4 S', 'BIKE', 'PETROL', 'MANUAL', 175.00, 300.00, 'https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=1200&q=80', 'Bred directly from MotoGP. Desmosedici Stradale engine with Öhlins Smart EC 2.0 electronic suspension and carbon aero wings.', 1, 4.9, 'Downtown Executive Hub', 'Öhlins Electronic Suspension, Cornering ABS EVO, Quick Shift Up/Down, Full TFT Display, Riding Modes', NULL, NULL, NULL, NULL, 1103, 'Superbike', 1),
(8, 'BIKE', 'BMW', 'R 1250 GS Adventure', 'BIKE', 'PETROL', 'MANUAL', 145.00, 250.00, 'https://images.unsplash.com/photo-1568772585407-9361f9bf3a87?auto=format&fit=crop&w=1200&q=80', 'The undisputed king of long-range globe-trotting adventure with Boxer ShiftCam torque and rugged alloy luggage carriers.', 1, 4.8, 'Suburban Plaza', 'ShiftCam Boxer Engine, Dynamic ESA, Heated Grips, Keyless Ride, Aluminum Panniers, Cruise Control', NULL, NULL, NULL, NULL, 1254, 'Adventure Touring', 1),
(9, 'BIKE', 'Harley-Davidson', 'Fat Boy 114', 'BIKE', 'PETROL', 'MANUAL', 150.00, 250.00, 'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=1200&q=80', 'Iconic cruiser presence with solid Lakester cast disc wheels, Milwaukee-Eight 114 muscle, and satin chrome finishes.', 1, 4.7, 'Airport Terminal A', 'Milwaukee-Eight 114 V-Twin, Solid Cast Wheels, Signature LED Lighting, Custom Dual Exhaust, Forward Foot Controls', NULL, NULL, NULL, NULL, 1868, 'Cruiser', 1),
(10, 'BIKE', 'Triumph', 'Bonneville T120', 'BIKE', 'PETROL', 'MANUAL', 115.00, 200.00, 'https://images.unsplash.com/photo-1609630875171-b1321377ee65?auto=format&fit=crop&w=1200&q=80', 'Timeless modern-classic British styling featuring rich parallel twin exhaust note, torque-assist clutch, and lightweight handling.', 1, 4.8, 'Downtown Executive Hub', 'Torque-Assist Clutch, Twin Analogue Dials, Wire-Spoke Wheels, LED Daylight Lamp, Switchable Traction Control', NULL, NULL, NULL, NULL, 1200, 'Modern Classic', 1)
